-- Generated by noctalia from home/noctalia/templates/nvim.lua in the NixOS
-- config, and rewritten on every palette change: edit the template, not this.

-- Noctalia's palette yields roughly three hues, so mapping roles straight onto
-- base16's six syntax accents makes strings match functions and keywords match
-- types. Each accent is instead rotated off primary or tertiary, staying in the
-- palette's hue family, with tone varied through the fixed/container roles.
-- base08 stays on error: base16 drives diagnostics and diff-deleted from it.
require('base16-colorscheme').setup({
  base00 = '{{colors.surface.default.hex}}',
  base01 = '{{colors.surface_container.default.hex}}',
  base02 = '{{colors.surface_container_high.default.hex}}',
  base03 = '{{colors.outline.default.hex}}',
  base04 = '{{colors.on_surface_variant.default.hex}}',
  base05 = '{{colors.on_surface.default.hex}}',
  base06 = '{{colors.on_surface.default.hex}}',
  base07 = '{{colors.on_background.default.hex}}',
  base08 = '{{colors.error.default.hex}}',
  base09 = '{{colors.tertiary_fixed.default.hex | rotate_hue -25}}',
  base0A = '{{colors.primary_fixed.default.hex | rotate_hue -35}}',
  base0B = '{{colors.primary.default.hex | rotate_hue 35}}',
  base0C = '{{colors.on_secondary_container.default.hex | rotate_hue -60}}',
  base0D = '{{colors.primary.default.hex}}',
  base0E = '{{colors.tertiary.default.hex}}',
  base0F = '{{colors.secondary_fixed.default.hex}}',
})
vim.g.colors_name = 'noctalia'

-- The same ANSI palette noctalia gives kitty, so :terminal matches it.
for i, colour in ipairs({
  '{{colors.terminal_normal_black.default.hex}}',
  '{{colors.terminal_normal_red.default.hex}}',
  '{{colors.terminal_normal_green.default.hex}}',
  '{{colors.terminal_normal_yellow.default.hex}}',
  '{{colors.terminal_normal_blue.default.hex}}',
  '{{colors.terminal_normal_magenta.default.hex}}',
  '{{colors.terminal_normal_cyan.default.hex}}',
  '{{colors.terminal_normal_white.default.hex}}',
  '{{colors.terminal_bright_black.default.hex}}',
  '{{colors.terminal_bright_red.default.hex}}',
  '{{colors.terminal_bright_green.default.hex}}',
  '{{colors.terminal_bright_yellow.default.hex}}',
  '{{colors.terminal_bright_blue.default.hex}}',
  '{{colors.terminal_bright_magenta.default.hex}}',
  '{{colors.terminal_bright_cyan.default.hex}}',
  '{{colors.terminal_bright_white.default.hex}}',
}) do
  vim.g['terminal_color_' .. (i - 1)] = colour
end

local hi = function(group, opts)
  vim.api.nvim_set_hl(0, group, opts)
end

-- base16 draws dividers in the foreground colour, far louder than a divider
-- should be. outline_variant is Material's role for decorative dividers;
-- outline is the stronger one meant to stay legible, so it marks the scope.
hi('WinSeparator', { fg = '{{colors.outline_variant.default.hex}}' })
hi('VertSplit', { fg = '{{colors.outline_variant.default.hex}}' })
-- indent-blankline only falls back to its own defaults when these are unset.
hi('IblIndent', { fg = '{{colors.outline_variant.default.hex}}' })
hi('IblScope', { fg = '{{colors.outline.default.hex}}' })

-- Panes stay transparent; the title and selection bars keep their blocks,
-- since those float over code where a background aids readability.
hi('TelescopeNormal',         { fg = '{{colors.on_surface.default.hex}}' })
hi('TelescopeBorder',         { fg = '{{colors.outline.default.hex}}' })
hi('TelescopePromptNormal',   { fg = '{{colors.on_surface.default.hex}}' })
hi('TelescopePromptBorder',   { fg = '{{colors.outline.default.hex}}' })
hi('TelescopePromptPrefix',   { fg = '{{colors.primary.default.hex}}' })
hi('TelescopePromptCounter',  { fg = '{{colors.on_surface_variant.default.hex}}' })
hi('TelescopePromptTitle',    { fg = '{{colors.surface.default.hex}}', bg = '{{colors.primary.default.hex}}' })
hi('TelescopePreviewTitle',   { fg = '{{colors.surface.default.hex}}', bg = '{{colors.secondary.default.hex}}' })
hi('TelescopeResultsTitle',   { fg = '{{colors.surface.default.hex}}', bg = '{{colors.tertiary.default.hex}}' })
hi('TelescopeSelection',      { fg = '{{colors.on_surface.default.hex}}', bg = '{{colors.surface_container_high.default.hex}}' })
hi('TelescopeSelectionCaret', { fg = '{{colors.primary.default.hex}}', bg = '{{colors.surface_container_high.default.hex}}' })
hi('TelescopeMatching',       { fg = '{{colors.primary.default.hex}}', bold = true })
